import string


def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(encoded_str: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in encoded_str])


# Additional improvements to the decode_shift function to handle uppercase letters as well
def decode_shift(encoded_str: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string, handling both
    uppercase and lowercase letters.
    """
    decoded_chars = []
    for ch in encoded_str:
        if 'a' <= ch <= 'z':
            decoded_chars.append(chr(((ord(ch) - ord('a') - 5) % 26) + ord('a')))
        elif 'A' <= ch <= 'Z':
            decoded_chars.append(chr(((ord(ch) - ord('A') - 5) % 26) + ord('A')))
        else:
            decoded_chars.append(ch)
    return "".join(decoded_chars)

