import math


def fib(n: int):
    if n <= 0:
        raise ValueError("Input must be a non-negative integer.")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        # Using the closed-form expression of the Fibonacci sequence
        # known as Binet's formula, which involves the golden ratio.
        phi = (1 + math.sqrt(5)) / 2
        return round(pow(phi, n - 1) / math.sqrt(5))

