def encode(message):
    vowels = 'aeiouAEIOU'
    encoded_message = ''

    for char in message:
        if char in vowels:
            # Find the index of the vowel in the alphabet, add 2 and wrap around if necessary
            if char.isupper():
                encoded_char = chr((ord(char) - ord('A') + 2) % 26 + ord('A'))
            else:
                encoded_char = chr((ord(char) - ord('a') + 2) % 26 + ord('a'))
        elif char.isalpha():
            # Swap case
            if char.isupper():
                encoded_char = char.lower()
            else:
                encoded_char = char.upper()
        else:
            # Keep non-letters as they are
            encoded_char = char

        encoded_message += encoded_char

    return encoded_message

