def minSubArraySum(nums):
    if not nums:
        return 0

    min_sum = sys.maxsize  # Initialize min_sum as maximum possible integer value
    current_sum = 0

    for num in nums:
        current_sum += num
        if current_sum < min_sum:
            min_sum = current_sum
        if current_sum > 0:
            current_sum = num

