def max_fill(grid, capacity):
    rows = len(grid)
    cols = len(grid[0])

    total_fills = 0

    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                total_fills += math.ceil(grid[row][col] / capacity)

    return total_fills

