import math


def tri(n):
    if n < 1:
        return []
    elif n == 1:
        return [3]
    result = [3]
    if n % 2 == 0:
        for _ in range(2, n + 1):
            result.append(result[-1] + result[-2] + result[-3] // 2)
    else:
        for _ in range(2, n + 1):
            result.append(result[-1] + result[-2] + tri(n - 1)[-1])
    result.append(tri(n)[-1])
    return result

